out<-'analysis/tasks/V3-I01/rev-1/work';b<-readRDS(file.path(out,'prepared.rds'))$base;b<-b[b$RIDAGEYR>=50&is.finite(b$weight_mec_18yr)&b$weight_mec_18yr>0,];rr<-list();for(candidate in c('FI_candidate36','FI_route','FI30'))for(retain in c(FALSE,TRUE)){d<-b[(!is.na(b[[candidate]]))==retain,];for(v in c('age','NLR','MLR','SIRI','SII')){x<-d[[v]];i<-is.finite(x);q<-quantile(x[i],c(.25,.5,.75));w<-d$weight_mec_18yr[i];o<-order(x[i]);xw<-x[i][o];cw<-cumsum(w[o])/sum(w);wq<-sapply(c(.25,.5,.75),function(p)xw[which(cw>=p)[1]]);rr[[length(rr)+1]]<-data.frame(candidate=candidate,retained=retain,variable=v,n=nrow(d),observed=sum(i),missing=sum(!i),q25=q[1],median=q[2],q75=q[3],weighted_q25=wq[1],weighted_median=wq[2],weighted_q75=wq[3],weighted_mean=sum(x[i]*w)/sum(w))}};write.csv(do.call(rbind,rr),file.path(out,'selection_continuous_distributions.csv'),row.names=FALSE)
